import copy
class Failing(list):
    armed=True
    def __deepcopy__(self,memo): return list(self)
    def trip(self):
        if self.armed:
            self.armed=False
            raise OSError('storage interruption')
    def append(self,value):
        super().append(value);self.trip()
    def extend(self,values):
        for value in values: self.append(value)
    def __iadd__(self,values): self.extend(values);return self
    def insert(self,*args):
        super().insert(*args);self.trip()
    def __setitem__(self,*args):
        super().__setitem__(*args);self.trip()

