import copy
class FailedWrite(dict):
    def __deepcopy__(self,memo): return copy.deepcopy(dict(self),memo)
    def _trip(self):
        if not getattr(self,"_failed",False):
            self._failed=True
            raise RuntimeError("storage")
    def __setitem__(self,*args,**kwargs):
        self._trip()
        return dict.__setitem__(self,*args,**kwargs)
    def __delitem__(self,*args,**kwargs):
        self._trip()
        return dict.__delitem__(self,*args,**kwargs)
    def update(self,*args,**kwargs):
        self._trip()
        return dict.update(self,*args,**kwargs)
    def setdefault(self,*args,**kwargs):
        self._trip()
        return dict.setdefault(self,*args,**kwargs)
    def __ior__(self,*args,**kwargs):
        self._trip()
        return dict.__ior__(self,*args,**kwargs)
    def clear(self,*args,**kwargs):
        self._trip()
        return dict.clear(self,*args,**kwargs)
    def pop(self,*args,**kwargs):
        self._trip()
        return dict.pop(self,*args,**kwargs)
    def popitem(self,*args,**kwargs):
        self._trip()
        return dict.popitem(self,*args,**kwargs)
